@IsTest(SeeAllData=false) private class ObjectTextEqualityObservation{
@IsTest static void ose01(){Map<String,Object> payload=new Map<String,Object>();try{Object left='NORTH';Object right='north';payload.put('objectEquals',left.equals(right));payload.put('operator',left==right);payload.put('typedEquals',((String)left).equals((String)right));}catch(Exception fault){payload.put('type',fault.getTypeName());payload.put('message',fault.getMessage());}System.assert(false,'OBJECT_TEXT_RESULT|OSE01|'+JSON.serialize(payload));}
@IsTest static void ose02(){Map<String,Object> payload=new Map<String,Object>();try{ObjectTextBox left=new ObjectTextBox('NORTH');ObjectTextBox same=new ObjectTextBox('NORTH');ObjectTextBox mixed=new ObjectTextBox('north');ObjectTextBox different=new ObjectTextBox('south');payload.put('same',new List<Boolean>{left.equals(same),left==same});payload.put('mixed',new List<Boolean>{left.equals(mixed),left==mixed});payload.put('different',new List<Boolean>{left.equals(different),left==different});payload.put('nullArgument',left.equals(null));}catch(Exception fault){payload.put('type',fault.getTypeName());payload.put('message',fault.getMessage());}System.assert(false,'OBJECT_TEXT_RESULT|OSE02|'+JSON.serialize(payload));}
}

